#!/usr/bin/env python3
# One-command updater for CCSDS-SAT-TTC-IP v2.26.5 (CR-20..CR-25 & Stage 10)
import base64
import zlib
from pathlib import Path

FILES = {
    'Makefile': '',
    'README.md': '',
    'ccsds_ttc_rtl_spec_and_live_plan.md': '',
    'rtl/ccsds_channel_impairment_model.sv': '',
    'rtl/ccsds_conv_viterbi_codec.sv': '',
    'rtl/ccsds_phy_modem.sv': '',
    'rtl/ccsds_sat_ttc_top.sv': '',
    'scripts/run_eda_sim.bat': '',
    'scripts/run_eda_sim.ps1': 'eNpVjcEKwjAQRO/5iiUUaUFr/QAPRXMQBIX2IKiUmG7LHpKWTYSC+O9Ge3KO84Y3o2ZtUwExVx+YXH9PKrKwBTl5snI5I3Ih9kH3GMmmEJlIFPPApQk0uDNjh4zOfKmswjBKsQBj2xwnhLUB6Q3TGPyNn67BVjdRnT90gN/XLJaCOkiTY1nV6nKod6e9gpVDKDJ4AU4Ux3/sLT40qjkO',
    'scripts/run_eda_sim.sh': '',
    'scripts/sv_rtl_audit.py': '',
    'tb/tb_stage10_full_matrix_link_stress.sv': '',
}

def main() -> None:
    root = Path(__file__).resolve().parent
    for rel, b64 in FILES.items():
        out_path = root / rel
        out_path.parent.mkdir(parents=True, exist_ok=True)
        data = zlib.decompress(base64.b64decode(b64))
        out_path.write_bytes(data)
        print(f'[UPDATED] {rel} ({len(data)} bytes)')
    print('\n[SUCCESS] Upgraded local repository to v2.26.5! Now run:')
    print('  .\\scripts\\run_eda_sim.bat xsim 10')

if __name__ == '__main__':
    main()